scan_table_check.script:
(function(engine, current) {
    var context = new global.EcsContext(current);
    if (context.flag('requires_authentication')) {
        return;
    }
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-REST-001',
        title: 'Scripted REST resource without authentication',
        recommendation: 'Turn on "Requires authentication" and control access with ACLs and "Requires ACL ' +
            'authorization". Leave it off only for endpoints deliberately meant to be public, and mute this ' +
            'finding with the reason.',
        current: current
    });
    report.addRecord('Scripted REST resource "' + context.value('name') + '" (' + context.value('http_method') + ' ' +
        context.value('operation_uri') + ') does not require authentication, so anyone can call it without logging in.');
    engine.finding.setCurrentSource(current);
    report.flush();
})(engine, current);
